-- Created by the Phase 5 data migration (scripts/db/migrate-mysql-to-postgres.mjs), inside the same transaction that copies the data.
-- It holds the names of the migrations that were applied to the ORIGINAL MySQL database (read from MySQL's sequelizemeta),
-- in their original order. It is history of the source, NOT the PostgreSQL migration history: PostgreSQL's own
-- sequelizemeta table is not touched, and none of these migrations is ever run against PostgreSQL.
CREATE TABLE "mysql_migration_history" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "name" varchar(255) NOT NULL,
  "copied_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "mysql_migration_history_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "mysql_migration_history_name_key" UNIQUE ("name")
);
COMMENT ON TABLE "mysql_migration_history" IS 'Migration names applied to the original MySQL database (copied once during the MySQL to PostgreSQL data migration). Not used by sequelize-cli.';
